import { GoogleGenAI, Type } from "@google/genai";
import { Modality, WorkspaceState } from "./types";

const MODEL_NAME = 'gemini-flash-latest';
const JSON_MODEL_NAME = 'gemini-3-flash-preview';

export const enhancePrompt = async (
  state: WorkspaceState,
  onChunk: (chunk: string) => void
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const systemInstruction = `
    You are a master Prompt Engineer specializing in multi-modal generative AI.
    Your task is to take a "Seed" idea and a set of "Parameters" to build a "Master Prompt".

    Guidelines:
    - For Image/Video: Focus on technical details like lighting, framing, lens types, and specific artistic styles.
    - For Code: Ensure the context is technical, specifying constraints, libraries, and design patterns.
    - For Audio: Focus on texture, instrumentation, vibe, and acoustic properties.
    - For Text: Focus on tone, target audience, and structural requirements.

    Output Format:
    Return ONLY the final optimized prompt. Do not include introductory text or explanations.
    If the modality is 'image' or 'video', structure it for Midjourney/Sora style syntax.
    If 'code', provide a clear instruction set.
  `;

  const parametersString = Object.entries(state.params)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ');

  const prompt = `
    Modality: ${state.modality.toUpperCase()}
    Seed Idea: ${state.seed}
    Technical Parameters: ${parametersString}

    Generate an optimized master prompt.
  `;

  try {
    const stream = await ai.models.generateContentStream({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction,
        thinkingConfig: state.isThinking ? { thinkingBudget: 24576 } : { thinkingBudget: 0 },
        temperature: 0.8,
      },
    });

    for await (const chunk of stream) {
      const text = chunk.text;
      if (text) onChunk(text);
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    onChunk("\n\n[Error: Failed to connect to the Jenga Engine. Check your network or API key.]");
  }
};

export const convertToJSON = async (promptText: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: JSON_MODEL_NAME,
      contents: `Structure the following AI prompt into a well-organized JSON object. Extract logical components such as 'core_objective', 'style_and_format', 'technical_constraints', and 'raw_prompt'. \n\nPrompt: ${promptText}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            core_objective: { type: Type.STRING },
            style_and_format: { type: Type.STRING },
            technical_constraints: { type: Type.ARRAY, items: { type: Type.STRING } },
            raw_prompt: { type: Type.STRING }
          },
          required: ["core_objective", "style_and_format", "raw_prompt"]
        }
      }
    });
    return response.text || '';
  } catch (error) {
    console.error("JSON Conversion Error:", error);
    return JSON.stringify({ error: "Failed to structure as JSON" }, null, 2);
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { MODALITIES, MODALITY_SPECIFIC_CONTROLS } from '../constants';
import { Modality, WorkspaceState, GeneratedPrompt, PromptTemplate } from '../types';
import { enhancePrompt, convertToJSON } from '../geminiService';

interface WorkspaceProps {
  onGenerated: (prompt: GeneratedPrompt) => void;
  initialTemplate: PromptTemplate | null;
  onClearTemplate: () => void;
}

export const Workspace: React.FC<WorkspaceProps> = ({ onGenerated, initialTemplate, onClearTemplate }) => {
  const [state, setState] = useState<WorkspaceState>({
    modality: 'text',
    seed: '',
    params: {},
    isThinking: false
  });

  const [output, setOutput] = useState('');
  const [jsonOutput, setJsonOutput] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'text' | 'json'>('text');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isConverting, setIsConverting] = useState(false);
  const outputRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialTemplate) {
      setState({
        modality: initialTemplate.modality,
        seed: initialTemplate.seed,
        params: initialTemplate.parameters,
        isThinking: false
      });
      onClearTemplate();
    }
  }, [initialTemplate, onClearTemplate]);

  useEffect(() => {
    if (outputRef.current) {
      outputRef.current.scrollTop = outputRef.current.scrollHeight;
    }
  }, [output, jsonOutput, viewMode]);

  const handleParamChange = (name: string, value: string) => {
    setState(prev => ({
      ...prev,
      params: { ...prev.params, [name]: value }
    }));
  };

  const handleGenerate = async () => {
    if (!state.seed.trim()) return;

    setIsGenerating(true);
    setOutput('');
    setJsonOutput(null);
    setViewMode('text');
    let fullOutput = '';

    await enhancePrompt(state, (chunk) => {
      fullOutput += chunk;
      setOutput(fullOutput);
    });

    setIsGenerating(false);

    onGenerated({
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      originalSeed: state.seed,
      enhancedPrompt: fullOutput,
      modality: state.modality,
      isBookmarked: false
    });
  };

  const handleConvertToJson = async () => {
    if (!output || isConverting) return;
    if (jsonOutput) {
      setViewMode('json');
      return;
    }

    setIsConverting(true);
    const structured = await convertToJSON(output);
    setJsonOutput(structured);
    setViewMode('json');
    setIsConverting(false);
  };

  const handleCopy = () => {
    const textToCopy = viewMode === 'json' ? jsonOutput || '' : output;
    navigator.clipboard.writeText(textToCopy);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <section className="space-y-4">
        <h2 className="text-sm font-bold uppercase tracking-widest text-indigo-400">1. Select Modality</h2>
        <div className="grid grid-cols-3 md:grid-cols-5 gap-3">
          {MODALITIES.map((m) => (
            <button
              key={m.value}
              onClick={() => setState(prev => ({ ...prev, modality: m.value, params: {} }))}
              className={`
                flex flex-col items-center justify-center p-4 rounded-2xl transition-all border
                ${state.modality === m.value 
                  ? 'bg-indigo-600/20 border-indigo-500/50 text-white' 
                  : 'bg-white/5 border-white/10 text-gray-400 hover:bg-white/10'}
              `}
            >
              <span className="text-2xl mb-2">{m.icon}</span>
              <span className="text-xs font-semibold">{m.label}</span>
            </button>
          ))}
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Input Column */}
        <section className="space-y-6">
          <div className="space-y-4">
            <h2 className="text-sm font-bold uppercase tracking-widest text-indigo-400">2. Define Seed Idea</h2>
            <textarea
              value={state.seed}
              onChange={(e) => setState(prev => ({ ...prev, seed: e.target.value }))}
              placeholder="Describe your core concept in plain English..."
              className="w-full h-40 glass rounded-2xl p-6 text-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all resize-none border-white/10"
            />
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-bold uppercase tracking-widest text-indigo-400">3. Technical Parameters</h2>
              <button 
                onClick={() => setState(prev => ({ ...prev, params: {} }))}
                className="text-[10px] text-gray-500 hover:text-white"
              >
                Reset Params
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {MODALITY_SPECIFIC_CONTROLS[state.modality].map((control) => (
                <div key={control.name} className="space-y-1.5">
                  <label className="text-[10px] font-bold text-gray-500 uppercase ml-1">{control.name}</label>
                  <select
                    value={state.params[control.name] || ''}
                    onChange={(e) => handleParamChange(control.name, e.target.value)}
                    className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:border-indigo-500/50 outline-none transition-colors"
                  >
                    <option value="" disabled>Select {control.name}...</option>
                    {control.options.map(opt => (
                      <option key={opt} value={opt} className="bg-gray-900">{opt}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-4">
            <button
              onClick={handleGenerate}
              disabled={isGenerating || !state.seed.trim()}
              className={`
                flex-1 w-full py-4 rounded-2xl font-bold text-lg transition-all shadow-2xl
                ${isGenerating || !state.seed.trim()
                  ? 'bg-gray-800 text-gray-500 cursor-not-allowed'
                  : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-500/20'}
              `}
            >
              {isGenerating ? (
                <div className="flex items-center justify-center gap-3">
                  <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                  Stacking Prompt Blocks...
                </div>
              ) : (
                'Generate Master Prompt'
              )}
            </button>

            <div className="flex items-center gap-3 px-4 py-3 glass rounded-2xl border-white/10">
              <label className="text-xs font-semibold text-gray-400">Deeper Reasoning</label>
              <button
                onClick={() => setState(prev => ({ ...prev, isThinking: !prev.isThinking }))}
                className={`w-12 h-6 rounded-full p-1 transition-colors ${state.isThinking ? 'bg-indigo-600' : 'bg-gray-700'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full shadow transition-transform ${state.isThinking ? 'translate-x-6' : 'translate-x-0'}`}></div>
              </button>
            </div>
          </div>
        </section>

        {/* Output Column */}
        <section className="space-y-4 flex flex-col h-full">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h2 className="text-sm font-bold uppercase tracking-widest text-indigo-400">4. Final Output</h2>
              {output && !isGenerating && (
                <div className="flex bg-white/5 rounded-lg p-0.5 border border-white/10">
                  <button 
                    onClick={() => setViewMode('text')}
                    className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${viewMode === 'text' ? 'bg-indigo-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    TEXT
                  </button>
                  <button 
                    onClick={handleConvertToJson}
                    disabled={isConverting}
                    className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all flex items-center gap-1 ${viewMode === 'json' ? 'bg-indigo-600 text-white' : 'text-gray-500 hover:text-gray-300'}`}
                  >
                    {isConverting && <div className="w-2 h-2 border-t-2 border-white rounded-full animate-spin"></div>}
                    JSON
                  </button>
                </div>
              )}
            </div>
            {output && (
              <button 
                onClick={handleCopy}
                className="text-[10px] text-indigo-400 hover:text-indigo-300 font-bold uppercase tracking-tighter"
              >
                Copy {viewMode.toUpperCase()}
              </button>
            )}
          </div>

          <div 
            ref={outputRef}
            className="flex-1 min-h-[400px] glass rounded-2xl p-8 mono text-sm leading-relaxed border-white/10 overflow-y-auto relative group"
          >
            {!output && !isGenerating ? (
              <div className="h-full flex flex-col items-center justify-center text-gray-500 space-y-4">
                <div className="grid grid-cols-2 gap-2 opacity-20">
                  <div className="w-8 h-4 bg-white rounded-sm"></div>
                  <div className="w-8 h-4 bg-white rounded-sm"></div>
                  <div className="w-12 h-4 bg-white rounded-sm"></div>
                  <div className="w-6 h-4 bg-white rounded-sm"></div>
                </div>
                <p className="text-center max-w-[200px]">Build your stack on the left to see the optimized result here.</p>
              </div>
            ) : (
              <div className="whitespace-pre-wrap animate-in fade-in duration-1000">
                {viewMode === 'text' ? output : (jsonOutput || 'Structuring...')}
                {isGenerating && viewMode === 'text' && <span className="inline-block w-2 h-5 bg-indigo-500 ml-1 animate-pulse align-middle"></span>}
              </div>
            )}

            {output && (
              <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                 <div className="bg-indigo-600/20 text-indigo-400 text-[10px] px-2 py-1 rounded border border-indigo-500/20 backdrop-blur-sm">
                   {viewMode === 'text' ? 'Master Prompt' : 'Structured JSON'}
                 </div>
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { GeneratedPrompt } from '../types';
import { convertToJSON } from '../geminiService';

interface ResultCardProps {
  prompt: GeneratedPrompt;
  onToggleBookmark: () => void;
}

export const ResultCard: React.FC<ResultCardProps> = ({ prompt, onToggleBookmark }) => {
  const [copied, setCopied] = useState(false);
  const [jsonView, setJsonView] = useState(false);
  const [jsonContent, setJsonContent] = useState<string | null>(null);
  const [isConverting, setIsConverting] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(jsonView && jsonContent ? jsonContent : prompt.enhancedPrompt);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleToggleJson = async () => {
    if (jsonView) {
      setJsonView(false);
      return;
    }

    if (jsonContent) {
      setJsonView(true);
      return;
    }

    setIsConverting(true);
    const structured = await convertToJSON(prompt.enhancedPrompt);
    setJsonContent(structured);
    setJsonView(true);
    setIsConverting(false);
  };

  const formatDate = (ts: number) => {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(ts);
  };

  return (
    <div className="glass rounded-2xl border-white/10 overflow-hidden hover:shadow-xl transition-shadow group">
      <div className="p-6 border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="w-8 h-8 rounded-lg bg-indigo-500/20 flex items-center justify-center text-sm">
            {prompt.modality === 'text' && '📝'}
            {prompt.modality === 'image' && '🎨'}
            {prompt.modality === 'video' && '🎬'}
            {prompt.modality === 'audio' && '🔊'}
            {prompt.modality === 'code' && '💻'}
          </span>
          <div>
            <h3 className="text-sm font-semibold text-gray-200 line-clamp-1">{prompt.originalSeed}</h3>
            <p className="text-[10px] text-gray-500 uppercase font-medium">{formatDate(prompt.timestamp)}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button 
            onClick={onToggleBookmark}
            className={`p-2 rounded-lg transition-colors ${prompt.isBookmarked ? 'text-yellow-400 bg-yellow-400/10' : 'text-gray-500 hover:bg-white/5'}`}
          >
            <svg className="w-5 h-5" fill={prompt.isBookmarked ? "currentColor" : "none"} stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.382-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z" />
            </svg>
          </button>
          <button 
            onClick={handleCopy}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${copied ? 'bg-green-600 text-white' : 'bg-white/5 hover:bg-white/10 text-gray-300'}`}
          >
            {copied ? 'Copied!' : 'Copy'}
          </button>
        </div>
      </div>

      <div className="p-6 bg-black/20">
        <div className="mono text-xs text-gray-400 leading-relaxed whitespace-pre-wrap max-h-48 overflow-y-auto">
          {jsonView ? (jsonContent || 'Structuring...') : prompt.enhancedPrompt}
        </div>
      </div>

      <div className="px-6 py-3 bg-white/5 flex items-center justify-between">
        <div className="flex gap-2">
          <span className="text-[10px] text-gray-500">Enhanced via Gemini 2.5 Flash</span>
        </div>
        <button 
          onClick={handleToggleJson}
          disabled={isConverting}
          className={`text-[10px] uppercase font-bold tracking-tighter transition-colors flex items-center gap-1 ${jsonView ? 'text-indigo-400' : 'text-gray-500 hover:text-white'}`}
        >
          {isConverting && <div className="w-2 h-2 border-t-2 border-indigo-400 rounded-full animate-spin"></div>}
          {jsonView ? 'View Raw Prompt' : 'Convert to JSON'}
        </button>
      </div>
    </div>
  );
};

