import React, { useState, useMemo } from 'react';
import { TEMPLATES } from '../constants';
import { PromptTemplate, Category } from '../types';

interface LibraryProps {
  onInject: (template: PromptTemplate) => void;
}

export const PromptLibrary: React.FC<LibraryProps> = ({ onInject }) => {
  const [search, setSearch] = useState('');
  const [selectedCategories, setSelectedCategories] = useState<Category[]>([]);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  // Extract all unique tags from templates
  const allTags = useMemo(() => {
    const tags = new Set<string>();
    TEMPLATES.forEach(t => t.tags?.forEach(tag => tags.add(tag)));
    return Array.from(tags).sort();
  }, []);

  const categories = Object.values(Category);

  const filteredTemplates = useMemo(() => {
    return TEMPLATES.filter(t => {
      const matchesSearch = 
        t.title.toLowerCase().includes(search.toLowerCase()) || 
        t.description.toLowerCase().includes(search.toLowerCase()) ||
        t.tags?.some(tag => tag.toLowerCase().includes(search.toLowerCase()));

      const matchesCategory = selectedCategories.length === 0 || selectedCategories.includes(t.category as Category);

      const matchesTags = selectedTags.length === 0 || selectedTags.every(tag => t.tags?.includes(tag));

      return matchesSearch && matchesCategory && matchesTags;
    });
  }, [search, selectedCategories, selectedTags]);

  const toggleCategory = (cat: Category) => {
    setSelectedCategories(prev => 
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    );
  };

  const toggleTag = (tag: string) => {
    setSelectedTags(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const clearFilters = () => {
    setSelectedCategories([]);
    setSelectedTags([]);
    setSearch('');
  };

  const hasActiveFilters = selectedCategories.length > 0 || selectedTags.length > 0 || search.length > 0;

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="space-y-6">
        {/* Search and Action Bar */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex-1 relative">
            <svg className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by title, description or tag..."
              className="w-full pl-12 pr-6 py-4 glass rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all border-white/10"
            />
          </div>

          {hasActiveFilters && (
            <button 
              onClick={clearFilters}
              className="text-xs font-bold text-indigo-400 hover:text-indigo-300 uppercase tracking-widest flex items-center gap-2 px-2"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
              Clear Filters
            </button>
          )}
        </div>

        {/* Categories Bar */}
        <div className="space-y-3">
          <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest ml-1">Categories</h4>
          <div className="flex items-center gap-2 overflow-x-auto pb-2 no-scrollbar">
            <button
              onClick={() => setSelectedCategories([])}
              className={`
                px-4 py-2 rounded-full text-xs font-semibold whitespace-nowrap transition-all
                ${selectedCategories.length === 0 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' 
                  : 'bg-white/5 text-gray-400 hover:bg-white/10'}
              `}
            >
              All
            </button>
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => toggleCategory(cat)}
                className={`
                  px-4 py-2 rounded-full text-xs font-semibold whitespace-nowrap transition-all flex items-center gap-2
                  ${selectedCategories.includes(cat) 
                    ? 'bg-indigo-600/30 border-indigo-500/50 text-white border' 
                    : 'bg-white/5 text-gray-400 hover:bg-white/10 border border-transparent'}
                `}
              >
                {selectedCategories.includes(cat) && (
                  <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                )}
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Tags Bar */}
        <div className="space-y-3">
          <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest ml-1">Sub-categories & Tags</h4>
          <div className="flex flex-wrap gap-2">
            {allTags.map(tag => (
              <button
                key={tag}
                onClick={() => toggleTag(tag)}
                className={`
                  px-3 py-1.5 rounded-lg text-[11px] font-medium transition-all
                  ${selectedTags.includes(tag)
                    ? 'bg-indigo-500 text-white'
                    : 'bg-indigo-500/10 text-indigo-300 hover:bg-indigo-500/20'}
                `}
              >
                #{tag}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredTemplates.map(template => (
          <div 
            key={template.id}
            className="glass rounded-2xl border-white/10 hover:border-indigo-500/30 transition-all group overflow-hidden flex flex-col"
          >
            <div className="p-6 flex-1">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[10px] font-bold uppercase px-2 py-0.5 bg-indigo-500/20 text-indigo-400 rounded">
                  {template.modality}
                </span>
                <span className="text-[10px] font-bold text-gray-500 uppercase">
                  {template.category}
                </span>
              </div>
              <h3 className="text-lg font-bold mb-2 group-hover:text-indigo-400 transition-colors">{template.title}</h3>
              <p className="text-sm text-gray-400 line-clamp-2 mb-4 leading-relaxed">
                {template.description}
              </p>

              <div className="flex flex-wrap gap-1.5 mb-4">
                {template.tags?.map(tag => (
                  <span key={tag} className="text-[9px] text-indigo-400 bg-indigo-500/5 px-1.5 py-0.5 rounded border border-indigo-500/10">
                    #{tag}
                  </span>
                ))}
              </div>

              <div className="flex flex-wrap gap-2 mt-auto">
                {Object.entries(template.parameters).map(([k, v]) => (
                  <span key={k} className="text-[9px] bg-white/5 border border-white/10 px-1.5 py-0.5 rounded text-gray-500">
                    {k}: {v}
                  </span>
                ))}
              </div>
            </div>

            <button 
              onClick={() => onInject(template)}
              className="w-full py-4 bg-white/5 border-t border-white/10 text-xs font-bold uppercase tracking-widest text-indigo-400 hover:bg-indigo-600 hover:text-white transition-all"
            >
              Inject to Workspace
            </button>
          </div>
        ))}

        {filteredTemplates.length === 0 && (
          <div className="col-span-full py-32 text-center glass rounded-2xl border-dashed border-2 border-white/5">
            <p className="text-gray-500 mb-2">No templates match your current filter combination.</p>
            <button 
              onClick={clearFilters}
              className="text-indigo-400 text-sm font-semibold hover:underline"
            >
              Reset all filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { Modality, WorkspaceState } from "./types";

const MODEL_NAME = 'gemini-flash-latest';
const JSON_MODEL_NAME = 'gemini-3-flash-preview';

/**
 * Maps API errors to human-readable troubleshooting messages.
 */
const getErrorMessage = (error: any): string => {
  const message = error?.message || "";
  const status = error?.status || 0;

  if (!process.env.API_KEY) {
    return "API Key missing. Please ensure the workspace environment is correctly configured.";
  }

  if (message.includes("API_KEY_INVALID") || status === 401 || status === 403) {
    return "Authentication failed. The API key provided is invalid or has insufficient permissions.";
  }

  if (message.includes("quota") || status === 429) {
    return "Rate limit exceeded. The Jenga Engine is cooling down; please wait a moment before trying again.";
  }

  if (message.includes("safety") || message.includes("blocked")) {
    return "Content blocked. The request triggered safety filters. Please refine your seed idea and technical parameters.";
  }

  if (status >= 500) {
    return "Server Error. Gemini is currently experiencing high load or internal issues. Please try again later.";
  }

  return `An unexpected error occurred: ${message || "Unknown connection error"}. Please check your network and try again.`;
};

export const enhancePrompt = async (
  state: WorkspaceState,
  onChunk: (chunk: string) => void
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const systemInstruction = `
    You are a master Prompt Engineer specializing in multi-modal generative AI.
    Your task is to take a "Seed" idea and a set of "Parameters" to build a "Master Prompt".

    Guidelines:
    - For Image/Video: Focus on technical details like lighting, framing, lens types, and specific artistic styles.
    - For Code: Ensure the context is technical, specifying constraints, libraries, and design patterns.
    - For Audio: Focus on texture, instrumentation, vibe, and acoustic properties.
    - For Text: Focus on tone, target audience, and structural requirements.

    Output Format:
    Return ONLY the final optimized prompt. Do not include introductory text or explanations.
    If the modality is 'image' or 'video', structure it for Midjourney/Sora style syntax.
    If 'code', provide a clear instruction set.
  `;

  const parametersString = Object.entries(state.params)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ');

  const prompt = `
    Modality: ${state.modality.toUpperCase()}
    Seed Idea: ${state.seed}
    Technical Parameters: ${parametersString}

    Generate an optimized master prompt.
  `;

  try {
    const stream = await ai.models.generateContentStream({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction,
        thinkingConfig: state.isThinking ? { thinkingBudget: 24576 } : { thinkingBudget: 0 },
        temperature: 0.8,
      },
    });

    for await (const chunk of stream) {
      const text = chunk.text;
      if (text) onChunk(text);
    }
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    const friendlyMessage = getErrorMessage(error);
    onChunk(`\n\n[ENGINE ERROR]\n${friendlyMessage}`);
  }
};

export const convertToJSON = async (promptText: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: JSON_MODEL_NAME,
      contents: `Structure the following AI prompt into a well-organized JSON object. Extract logical components such as 'core_objective', 'style_and_format', 'technical_constraints', and 'raw_prompt'. \n\nPrompt: ${promptText}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            core_objective: { type: Type.STRING },
            style_and_format: { type: Type.STRING },
            technical_constraints: { type: Type.ARRAY, items: { type: Type.STRING } },
            raw_prompt: { type: Type.STRING }
          },
          required: ["core_objective", "style_and_format", "raw_prompt"]
        }
      }
    });
    return response.text || '';
  } catch (error: any) {
    console.error("JSON Conversion Error:", error);
    const friendlyMessage = getErrorMessage(error);
    return JSON.stringify({ error: "Structure conversion failed", message: friendlyMessage }, null, 2);
  }
};
